        require($.nextNonce != 0, EmptyMMR());
        require(leafIndex < $.nextNonce, LeafIndexOutOfBounds());

        (uint256 leafNodePos, uint256 mountainHeight, uint64 leafIdxInMountain, bytes32[] memory otherPeaks) =
